-- Import the bundled starter schemes into Supabase for review.
-- Rows are pending until official sources and current details are reviewed.
with local_schemes as (
  select *
  from jsonb_to_recordset($local_data$[{"id":"local-pm-usp-csss","name":"PM-USP Central Sector Scheme of Scholarship for College and University Students","summary":"Merit-cum-means support for eligible students entering regular undergraduate courses. The NSP lists the 2026–27 fresh application window as open through 30 November 2026.","description":"Fresh applicants must meet the board merit-list condition, be in the first year of a regular graduation course, and satisfy the income and other conditions in the current official guidelines. Renewal applicants have separate conditions.","government_level":"central","state_name":null,"category":"Merit based","education_levels":["Undergraduate","Postgraduate"],"eligible_courses":[],"target_categories":["General","SC","ST","OBC","EWS"],"amount_min":null,"amount_max":null,"annual_income_limit":null,"application_start":"2026-06-02","application_end":"2026-11-30","application_status":"open","verification_status":"verified","official_url":"https://scholarships.gov.in/Students","information_source_url":"https://scholarships.gov.in/public/schemeGuidelines/FAQ_DOHE_CSSS.pdf?v=1","last_verified_at":"2026-11-24T00:00:00.000Z","other_conditions":"The 2025–26 Ministry FAQ reports annual support of ₹12,000 at graduation level for the first three years and ₹20,000 for postgraduate level; technical-course rates differ. Fresh-applicant criteria and award rates must be checked against the current year guidelines.","required_documents":["Class XII marksheet","Family income certificate","Category certificate if applicable","Disability certificate if applicable"],"application_procedure":"Check the current scheme specifications and apply through the National Scholarship Portal (NSP). SchemeSetu does not submit applications.","eligibility_rules":[{"field_name":"family_income","operator":"lte","expected_value":450000,"is_required":true,"source_note":"Annual family income up to ₹4.5 lakh, per the 2025–26 Ministry FAQ.","criterion_type":"family_income","criterion_value":450000,"is_mandatory":true,"condition_group":"main","condition_operator":"AND","group_operator":"AND","source_url":"https://scholarships.gov.in/public/schemeGuidelines/FAQ_DOHE_CSSS.pdf?v=1","verification_status":"verified","last_verified_at":"2026-11-24T00:00:00.000Z","academic_year":"2025-26"},{"field_name":"top_20_percentile","operator":"truthy","expected_value":true,"is_required":true,"source_note":"Fresh applicants must meet the relevant board merit-list condition; confirm the current year specification.","criterion_type":"top_20_percentile","criterion_value":true,"is_mandatory":true,"condition_group":"main","condition_operator":"AND","group_operator":"AND","source_url":"https://scholarships.gov.in/public/schemeGuidelines/FAQ_DOHE_CSSS.pdf?v=1","verification_status":"verified","last_verified_at":"2026-11-24T00:00:00.000Z","academic_year":"2025-26"},{"field_name":"regular_course","operator":"truthy","expected_value":true,"is_required":true,"source_note":"Regular course; correspondence and distance mode are excluded in the FAQ.","criterion_type":"regular_course","criterion_value":true,"is_mandatory":true,"condition_group":"main","condition_operator":"AND","group_operator":"AND","source_url":"https://scholarships.gov.in/public/schemeGuidelines/FAQ_DOHE_CSSS.pdf?v=1","verification_status":"verified","last_verified_at":"2026-11-24T00:00:00.000Z","academic_year":"2025-26"},{"field_name":"receiving_other_scholarship","operator":"truthy","expected_value":false,"is_required":true,"source_note":"The FAQ excludes students receiving another scholarship or fee reimbursement.","criterion_type":"receiving_other_scholarship","criterion_value":false,"is_mandatory":true,"condition_group":"main","condition_operator":"AND","group_operator":"AND","source_url":"https://scholarships.gov.in/public/schemeGuidelines/FAQ_DOHE_CSSS.pdf?v=1","verification_status":"verified","last_verified_at":"2026-11-24T00:00:00.000Z","academic_year":"2025-26"},{"field_name":"education_level","operator":"neq","expected_value":"Diploma","is_required":true,"source_note":"Diploma students are excluded under the FAQ.","criterion_type":"education_level","criterion_value":"Diploma","is_mandatory":true,"condition_group":"main","condition_operator":"AND","group_operator":"AND","source_url":"https://scholarships.gov.in/public/schemeGuidelines/FAQ_DOHE_CSSS.pdf?v=1","verification_status":"verified","last_verified_at":"2026-11-24T00:00:00.000Z","academic_year":"2025-26"}],"academic_year":"2026-27","benefits":"2025-26 Ministry FAQ: rates varied by course and year (?12,000 to ?20,000 annually). Confirm the 2026-27 rates on the current scheme guidelines."},{"id":"local-pm-yasasvi-school","name":"PM YASASVI Top Class Education in Schools for OBC, EBC and DNT Students","summary":"Central scholarship scheme for eligible OBC, EBC and DNT students in school education. NSP lists the 2026–27 application window through 30 November 2026, with a notice that some state applications are pending.","government_level":"central","state_name":null,"category":"Welfare based","education_levels":["School"],"eligible_courses":[],"target_categories":["OBC","EBC","DNT"],"amount_min":null,"amount_max":null,"annual_income_limit":null,"application_start":"2026-10-22","application_end":"2026-11-30","application_status":"open","verification_status":"verified","official_url":"https://scholarships.gov.in/Students","information_source_url":"https://scholarships.gov.in/All-Scholarships","last_verified_at":"2026-11-24T00:00:00.000Z","other_conditions":"The NSP announcement says fresh applications are open and notes that applicants from Rajasthan, Keralam and Karnataka should check the portal for state-specific availability.","required_documents":[],"application_procedure":"Check state availability and the current scheme specifications on NSP before applying.","eligibility_rules":[{"field_name":"social_categories","operator":"contains","expected_value":"OBC","is_required":false,"source_note":"The scheme title names OBC, EBC and DNT groups; exact conditions are in the official specifications.","criterion_type":"social_categories","criterion_value":"OBC","is_mandatory":false,"condition_group":"main","condition_operator":"AND","group_operator":"AND","source_url":"https://scholarships.gov.in/All-Scholarships","verification_status":"verified","last_verified_at":"2026-11-24T00:00:00.000Z"}],"academic_year":"2026-27"},{"id":"local-pm-yasasvi-college","name":"PM YASASVI Top Class Education in College for OBC, EBC and DNT Students","summary":"Central scholarship scheme for eligible OBC, EBC and DNT students in college education. NSP lists the 2026–27 application window through 30 November 2026.","government_level":"central","state_name":null,"category":"Welfare based","education_levels":["Undergraduate","Postgraduate"],"eligible_courses":[],"target_categories":["OBC","EBC","DNT"],"amount_min":null,"amount_max":null,"annual_income_limit":null,"application_start":"2026-06-01","application_end":"2026-11-30","application_status":"open","verification_status":"verified","official_url":"https://scholarships.gov.in/Students","information_source_url":"https://scholarships.gov.in/All-Scholarships","last_verified_at":"2026-11-24T00:00:00.000Z","other_conditions":"Check the current official scheme specifications for institution, course, income and award conditions.","required_documents":[],"application_procedure":"Check the current scheme specifications and apply through NSP.","eligibility_rules":[],"academic_year":"2026-27"},{"id":"local-sc-top-class","name":"Central Sector Scholarship of Top Class Education for SC Students","summary":"Central scheme for eligible SC students pursuing higher education. NSP lists the 2026–27 application window through 30 November 2026.","government_level":"central","state_name":null,"category":"Merit based","education_levels":["Undergraduate","Postgraduate"],"eligible_courses":[],"target_categories":["SC"],"amount_min":null,"amount_max":null,"annual_income_limit":null,"application_start":"2026-06-01","application_end":"2026-11-30","application_status":"open","verification_status":"verified","official_url":"https://scholarships.gov.in/Students","information_source_url":"https://scholarships.gov.in/All-Scholarships","last_verified_at":"2026-11-24T00:00:00.000Z","other_conditions":"Check the official specifications for eligible institutions, income limits, covered costs and award conditions.","required_documents":[],"application_procedure":"Check the current scheme specifications and apply through NSP.","eligibility_rules":[],"academic_year":"2026-27"},{"id":"local-disability-post-matric","name":"Post Matric Scholarship for Students with Disabilities","summary":"National scholarship for students with disabilities pursuing post-matric education. NSP lists the 2026–27 application window through 30 November 2026.","government_level":"central","state_name":null,"category":"Welfare based","education_levels":["Diploma","Undergraduate","Postgraduate","Doctoral"],"eligible_courses":[],"target_categories":["Disability"],"amount_min":null,"amount_max":null,"annual_income_limit":null,"application_start":"2026-07-25","application_end":"2026-11-30","application_status":"open","verification_status":"verified","official_url":"https://scholarships.gov.in/Students","information_source_url":"https://scholarships.gov.in/All-Scholarships","last_verified_at":"2026-11-24T00:00:00.000Z","other_conditions":"The NSP currently instructs disabled applicants to complete UDID portal consent before submitting an application. Check current scheme specifications for remaining conditions.","required_documents":[],"application_procedure":"Complete the required UDID consent, then review the scheme and apply through NSP.","eligibility_rules":[{"field_name":"disability","operator":"truthy","expected_value":true,"is_required":true,"source_note":"The scheme is for students with disabilities; check the current specifications for formal criteria.","criterion_type":"disability","criterion_value":true,"is_mandatory":true,"condition_group":"main","condition_operator":"AND","group_operator":"AND","source_url":"https://scholarships.gov.in/All-Scholarships","verification_status":"verified","last_verified_at":"2026-11-24T00:00:00.000Z"}],"academic_year":"2026-27"},{"id":"local-aicte-pragati-degree","name":"AICTE Pragati Scholarship for Girl Students (Technical Degree)","summary":"AICTE scholarship scheme for eligible girl students in technical degree education. NSP lists the 2026–27 application window through 30 November 2026.","government_level":"central","state_name":null,"category":"Merit based","education_levels":["Undergraduate"],"eligible_courses":["Technical degree"],"target_categories":["Women"],"amount_min":null,"amount_max":null,"annual_income_limit":null,"application_start":"2026-06-01","application_end":"2026-11-30","application_status":"open","verification_status":"verified","official_url":"https://scholarships.gov.in/Students","information_source_url":"https://scholarships.gov.in/All-Scholarships","last_verified_at":"2026-11-24T00:00:00.000Z","other_conditions":"Check the AICTE/NSP current-year specifications for family income, admission and award conditions.","required_documents":[],"application_procedure":"Review the current AICTE Pragati specifications on NSP and apply through the portal.","eligibility_rules":[],"academic_year":"2026-27"},{"id":"local-aicte-saksham-degree","name":"AICTE Saksham Scholarship for Specially Abled Students (Technical Degree)","summary":"AICTE scholarship scheme for eligible specially abled students in technical degree education. NSP lists the 2026–27 application window through 30 November 2026.","government_level":"central","state_name":null,"category":"Welfare based","education_levels":["Undergraduate"],"eligible_courses":["Technical degree"],"target_categories":["Disability"],"amount_min":null,"amount_max":null,"annual_income_limit":null,"application_start":"2026-06-01","application_end":"2026-11-30","application_status":"open","verification_status":"verified","official_url":"https://scholarships.gov.in/Students","information_source_url":"https://scholarships.gov.in/All-Scholarships","last_verified_at":"2026-11-24T00:00:00.000Z","other_conditions":"The NSP currently instructs disabled applicants to complete UDID portal consent before submitting an application. Check AICTE specifications for formal criteria.","required_documents":[],"application_procedure":"Complete the required UDID consent, then review current AICTE specifications and apply through NSP.","eligibility_rules":[],"academic_year":"2026-27"},{"id":"local-nmms","name":"National Means-cum-Merit Scholarship (NMMS)","summary":"National scholarship scheme for meritorious students. NSP lists the 2026–27 student application deadline as 15 November 2026; confirm any state-level notices or later extensions on NSP.","government_level":"central","state_name":null,"category":"Merit based","education_levels":["School"],"eligible_courses":[],"target_categories":[],"amount_min":null,"amount_max":null,"annual_income_limit":null,"application_start":"2026-06-01","application_end":"2026-11-15","application_status":"closed","verification_status":"verified","official_url":"https://scholarships.gov.in/Students","information_source_url":"https://scholarships.gov.in/All-Scholarships","last_verified_at":"2026-11-24T00:00:00.000Z","other_conditions":"Check the latest Ministry and state-level instructions for eligibility, exam and application process.","required_documents":[],"application_procedure":"Check the NSP and state education department notices for the current application cycle.","eligibility_rules":[],"academic_year":"2026-27"}]$local_data$::jsonb) as x(
    id text,
    name text,
    summary text,
    description text,
    government_level text,
    state_name text,
    category text,
    education_levels text[],
    eligible_courses text[],
    target_categories text[],
    amount_min numeric,
    amount_max numeric,
    annual_income_limit numeric,
    application_start date,
    application_end date,
    official_url text,
    information_source_url text,
    other_conditions text,
    required_documents text[],
    application_procedure text,
    academic_year text,
    benefits text
  )
)
insert into public.scholarships (
  external_identifier, name, summary, description, government_level,
  state_name, category, education_levels, eligible_courses, target_categories,
  amount_min, amount_max, annual_income_limit, application_start, application_end,
  application_status, verification_status, official_url, information_source_url,
  other_conditions, required_documents, application_procedure, academic_year, benefits
)
select
  id, name, summary, description, government_level::government_level,
  state_name, category, coalesce(education_levels, '{}'), coalesce(eligible_courses, '{}'), coalesce(target_categories, '{}'),
  amount_min, amount_max, annual_income_limit, application_start, application_end,
  'unknown'::application_status, 'pending'::verification_status,
  official_url, information_source_url, other_conditions, coalesce(required_documents, '{}'),
  application_procedure, academic_year, benefits
from local_schemes
on conflict (external_identifier, government_level, (coalesce(state_name, '')))
  where external_identifier is not null
  do nothing;
